from typing import List, Dict, Optional
from pydantic import BaseModel, Field


class DescriptionResult(BaseModel):
    """The structured copywriting generated by the Description Agent."""
    product_title: str = Field(description="SEO-optimized marketing title.")
    short_description: str = Field(description="A concise 1-2 sentence hook summarizing the value proposal.")
    long_description: str = Field(description="Detailed HTML formatting narrative of the course or kit.")
    key_features: List[str] = Field(description="Bullet points of outstanding structural features.")
    benefits: List[str] = Field(description="Key practical advantages for students/parents.")
    learning_outcomes: List[str] = Field(description="Core intellectual outcomes obtained upon completion.")
    course_modules: List[str] = Field(description="Structure list of modules or kit steps.")
    prerequisites: List[str] = Field(description="Core base requirements needed.")
    faq: List[Dict[str, str]] = Field(description="E.g., [{'question': '...', 'answer': '...'}]")
    specifications: Dict[str, str] = Field(description="Structural dimensions, weight, software, or age details.")


class DescriptionResponse(BaseModel):
    """Structured response wrap returned by the Description Agent."""
    status: str = Field(description="Result of execution: 'success' or 'failed'.")
    errors: List[str] = Field(default_factory=list, description="List of processing error messages.")
    description: Optional[DescriptionResult] = Field(default=None, description="The validated structured copy details.")
